#include "cjk_fonts.hpp"
#include <stddef.h>

struct CjkGlyphEntry {
  uint32_t codepoint;
  uint32_t bitmap_index;
  uint8_t adv_w;
  uint8_t box_w;
  uint8_t box_h;
  int8_t ofs_x;
  int8_t ofs_y;
};

struct CjkFontTable {
  const uint8_t* bitmap;
  const CjkGlyphEntry* entries;
  size_t count;
};

static const CjkGlyphEntry* findCjkGlyph(const CjkFontTable* tbl, uint32_t letter) {
  if (!tbl || tbl->count == 0) return nullptr;
  size_t lo = 0, hi = tbl->count;
  while (lo < hi) {
    size_t mid = lo + (hi - lo) / 2;
    uint32_t cp = tbl->entries[mid].codepoint;
    if (cp == letter) return &tbl->entries[mid];
    if (cp < letter) lo = mid + 1;
    else hi = mid;
  }
  return nullptr;
}

static bool cjkGetGlyphDsc(const lv_font_t* font, lv_font_glyph_dsc_t* dsc_out, uint32_t letter, uint32_t /*letter_next*/) {
  const auto* tbl = static_cast<const CjkFontTable*>(font->dsc);
  const CjkGlyphEntry* g = findCjkGlyph(tbl, letter);
  if (!g) return false;
  dsc_out->resolved_font = font;
  dsc_out->adv_w = g->adv_w;
  dsc_out->box_w = g->box_w;
  dsc_out->box_h = g->box_h;
  dsc_out->ofs_x = g->ofs_x;
  dsc_out->ofs_y = g->ofs_y;
  dsc_out->bpp = 4;
  dsc_out->is_placeholder = 0;
  return true;
}

static const uint8_t* cjkGetGlyphBitmap(const lv_font_t* font, uint32_t letter) {
  const auto* tbl = static_cast<const CjkFontTable*>(font->dsc);
  const CjkGlyphEntry* g = findCjkGlyph(tbl, letter);
  if (!g) return nullptr;
  return &tbl->bitmap[g->bitmap_index];
}

